'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `lastIndexOf` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'lastIndexOf' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.lastIndexOf ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.lastIndexOf.call( value, 1 );
		};
	}
});

tape( 'the method returns the index of the last element strictly equal to a search element', function test( t ) {
	var Point;
	var idx;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 1 ] );

	idx = p.lastIndexOf( 1 );
	t.strictEqual( idx, 2, 'returns expected value' );

	idx = p.lastIndexOf( 2 );
	t.strictEqual( idx, 1, 'returns expected value' );

	t.end();
});

tape( 'the method returns `-1` if unable to locate a search element', function test( t ) {
	var Point;
	var idx;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	idx = p.lastIndexOf( 10 );
	t.strictEqual( idx, -1, 'returns expected value' );

	t.end();
});

tape( 'the method supports specifying a starting index', function test( t ) {
	var Point;
	var idx;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 1 ] );

	idx = p.lastIndexOf( 1, 1 );
	t.strictEqual( idx, 0, 'returns expected value' );

	t.end();
});

tape( 'the method supports specifying a negative starting index', function test( t ) {
	var Point;
	var idx;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 1 ] );

	idx = p.lastIndexOf( 1, -1 );
	t.strictEqual( idx, 2, 'returns expected value' );

	t.end();
});

tape( 'the method returns `-1` if the starting index resolves to an index less than zero', function test( t ) {
	var Point;
	var idx;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	idx = p.lastIndexOf( 1, -10 );
	t.strictEqual( idx, -1, 'returns expected value' );

	t.end();
});

tape( 'the method does not distinguish between signed and unsigned zero', function test( t ) {
	var Point;
	var idx;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ -0.0, 0.0 ] );

	idx = p.lastIndexOf( 0.0 );
	t.strictEqual( idx, 1, 'returns expected value' );

	idx = p.lastIndexOf( -0.0 );
	t.strictEqual( idx, 1, 'returns expected value' );

	t.end();
});

tape( 'the method returns `-1` when searching for NaN', function test( t ) {
	var Point;
	var idx;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ NaN, 1 ] );

	idx = p.lastIndexOf( NaN );
	t.strictEqual( idx, -1, 'returns expected value' );

	t.end();
});
